function ringRoute(fx,fz,tx,tz){const pts=[],R0=LR+3.2,a0=Math.atan2(fz,fx),a1=Math.atan2(tz,tx);let da=((a1-a0)%(Math.PI*2)+Math.PI*3)%(Math.PI*2)-Math.PI;
  const steps=Math.max(1,Math.ceil(Math.abs(da)/.12));if(Math.hypot(fx,fz)<LR+2)pts.push({x:Math.cos(a0)*R0,z:Math.sin(a0)*R0});for(let i=1;i<=steps;i++){const a=a0+da*i/steps;pts.push({x:Math.cos(a)*R0,z:Math.sin(a)*R0});}pts.push({x:tx,z:tz});return pts;}
