const gearHTML=(g,btns='')=>{const s=SYS.gearStats(D,g),sl=SYS.slotCount(D,g);return `<div class="charm gear" style="--gc:${(D.RODS.find(r=>r.k===g.k)||{}).rc||['#aab4c0','#5fc48a','#4ea3ea','#3fb8b0','#ef8fb0','#f4a62a','#4a5ab8','#c46cf2'][D.RODS.findIndex(r=>r.k===g.k)]}"><div class="cico">${RIMG(g.k)}</div><div class="meta"><b>${s.n}</b> ${RGB(g.k)}${GGR(g)} <span class="star">${'★'.repeat(g.star)}<i>${'☆'.repeat(D.GEAR.starMax-g.star)}</i></span> <span class="plus">+${g.enh}</span>${g.id===S.rodId?' <span class="gbadge" style="--gc:#5fc48a">장착중</span>':''}${g.lock?' 🔒':''}<br>
 <span class="small">기본: ${rodOptTxt(s)}${g.br!=null?` <span class="muted" title="기본옵션 = 표기 수치 × ${SYS.bRange(D).map(x=>Math.round(x*100)).join('~')}% 랜덤">(${Math.round(SYS.baseMul(D,g)*100)}%)</span>`:''}</span><br>${g.extra.map(e=>`<span class="opt" data-tip="${D.CHARM.opts[e.k].n}: ${D.CHARM.opts[e.k].d}
낚싯대 추가옵션 (상자 등급 ${TIER(g.tier||1).n} 굴림) · 범위 ${D.GEAR.optRange?D.GEAR.optRange(g,e.k).join('~'):''}%">${D.CHARM.opts[e.k].n} <b>+${e.v}%</b></span>`).join(' ')}${Array(Math.max(0,sl-g.extra.length)).fill('<span class="opt muted">빈 슬롯</span>').join('')}${sl<D.GEAR.slots[g.k]+D.GEAR.starSlot.length?`<span class="opt muted">🔒 ★${D.GEAR.starSlot.find(x=>x>g.star)} 해금</span>`:''}</div>${btns}</div>`;};
