const RGB=k=>{const r=D.RODS.find(x=>x.k===k);return r&&r.rg?`<span class="rgb ${r.rg==='초월'?'tx':''}" style="--rc:${r.rc}">${r.rg}</span> `:'';},RIMG=(k,cls='rimg')=>`<img class="${cls}" src="img/rods/${k}.png" alt="" draggable="false">`,BIMG=(k,cls='rimg')=>`<img class="${cls}" src="img/baits/${k}.png" alt="" draggable="false">`;
