 function applyGrants(map){const RT=window.NK_RT||{};const srv=Number.isFinite(+RT.serverNow)?+RT.serverNow:afNow();const o={};if(map&&typeof map==='object')for(const k in map){const t=+map[k]||0;if(t>srv)o[nickKey(k)]=Math.max(+o[nickKey(k)]||0,t);}const personal=+RT.grantMine||0;if(personal>srv){for(const k of myAfKeys())o[k]=Math.max(+o[k]||0,personal);}afSave(o);try{updAutoBtn();}catch(e){}let mine=0;for(const k of myAfKeys())mine=Math.max(mine,+o[k]||0);if(mine>srv&&mine!==(+S.afSeenUntil||0)){S.afSeenUntil=mine;try{save();}catch(e){}alertBox('<h3>🤖 자동낚시</h3><p>자동낚시를 <b>'+afFmt(Math.max(0,mine-afNow()))+'</b> 동안 쓸 수 있어요.</p>');}const adm=$('admin');if(adm&&adm.classList.contains('show')&&AD.tab==='user'){try{keepScroll('admin',admin);}catch(e){}}}
